<?php
 declare(strict_types=1);
 namespace Namira;
 use PDO;
 final class StoreManager {
 public function __construct(private PDO $db,private array $actor){if(!Permissions::allows($db,$actor,'shop.manage'))throw new HttpError(403,'مجوز مدیریت فروشگاه لازم است.');if(!StoreSchema::ready($db))throw new HttpError(503,'ارتقای فروشگاه اجرا نشده است.');}
 private function audit(string $action,string $entity,int $id,array $before,array $after,string $reason=''):void {Db::insert($this->db,'store_audit',['user_id'=>$this->actor['id'],'action'=>$action,'entity'=>$entity,'entity_id'=>$id,'before_value'=>Protocol::encode($before),'after_value'=>Protocol::encode($after),'reason'=>$reason,'created_at'=>date(DATE_ATOM)]);}
 private static function slug(array $in,string $field='slug'):string {$s=Security::text($in,$field,150);if(!preg_match('/^[\p{L}\p{N}][\p{L}\p{N}_-]*$/uD',$s))throw new HttpError(422,'نامک فقط شامل حرف، عدد و خط تیره باشد.');return $s;}
 private static function choice(array $in,string $key,array $choices):string {$s=Security::text($in,$key,30);if(!isset($choices[$s]))throw new HttpError(422,'مقدار '.$key.' معتبر نیست.');return $s;}
 public function product(array $in,int $id=0):int {
 return Db::transaction($this->db,function()use($in,$id){
 $before=$id?(new StoreCatalog($this->db))->get($id,true):[];
 if($id){Db::query($this->db,'SELECT id FROM products WHERE id=?'.($this->db->getAttribute(PDO::ATTR_DRIVER_NAME)==='mysql'?' FOR UPDATE':''),[$id])->fetch();$current=(int)(Db::query($this->db,'SELECT revision FROM store_product_details WHERE product_id=?',[$id])->fetchColumn()?:0);if(StoreCatalog::integer($in['revision']??-1)!==$current)throw new HttpError(409,'محصول در پنجره دیگری تغییر کرده؛ پیش از ذخیره دوباره بررسی کنید.');}
 $slug=self::slug($in);if(Db::query($this->db,'SELECT product_id FROM store_product_details WHERE slug=? AND product_id<>?',[$slug,$id])->fetchColumn())throw new HttpError(422,'نامک تکراری است.');
 $data=['title'=>Security::text($in,'title',255),'description'=>Security::text($in,'description',30000,false),'category'=>Security::text($in,'legacy_category',100,false),'published'=>!empty($in['published'])?1:0];
 if($id)Db::query($this->db,'UPDATE products SET title=?,description=?,category=?,published=? WHERE id=?',[...array_values($data),$id]);else $id=Db::insert($this->db,'products',$data);
 $meta=$before['meta']??[];
 foreach(['summary'=>1000,'tags'=>1000,'specifications'=>10000,'preparation'=>1000,'sales_terms'=>12000,'digital_rights'=>12000,'seo_description'=>320] as $key=>$limit)if(array_key_exists($key,$in))$meta[$key]=Security::text($in,$key,$limit,false);
 if(array_key_exists('digital_files_present',$in)&&(!is_array($in['digital_files']??[])||count($in['digital_files']??[])>100))throw new HttpError(422,'فهرست فایل‌ها معتبر نیست.');$meta['digital_files']=array_key_exists('digital_files_present',$in)?array_map(fn($v)=>StoreCatalog::integer($v,1),$in['digital_files']??[]):($meta['digital_files']??null);if(is_array($meta['digital_files']))foreach($meta['digital_files'] as $fid)if(!Db::query($this->db,"SELECT id FROM store_files WHERE id=? AND product_id=? AND kind='catalog' AND active=1",[$fid,$id])->fetchColumn())throw new HttpError(422,'فایل انتخابی متعلق به محصول نیست.');
 $meta['related_ids']=array_key_exists('related_ids_text',$in)?array_values(array_unique(array_filter(array_map('intval',explode(',',Security::text($in,'related_ids_text',1000,false)))))):($meta['related_ids']??[]);if(count($meta['related_ids'])>30)throw new HttpError(422,'حداکثر ۳۰ محصول مرتبط انتخاب کنید.');
 $meta['revision_limit']=array_key_exists('revision_limit',$in)?StoreCatalog::integer($in['revision_limit'],0,1000):($meta['revision_limit']??0);$meta['form_id']=array_key_exists('form_id',$in)?StoreCatalog::integer($in['form_id']?:0):($meta['form_id']??0);$meta['weight_grams']=array_key_exists('weight_grams',$in)?StoreCatalog::integer($in['weight_grams']?:0,0,10000000):($meta['weight_grams']??0);if($meta['form_id']&&!Db::query($this->db,'SELECT id FROM store_forms WHERE id=?',[$meta['form_id']])->fetchColumn())throw new HttpError(422,'فرم محصول پیدا نشد.');
 $meta['customer_approval']=array_key_exists('approval_present',$in)||array_key_exists('customer_approval',$in)?!empty($in['customer_approval']):($meta['customer_approval']??false); // default off; no automatic design engine
 $detail=['slug'=>$slug,'delivery'=>self::choice($in,'delivery',StoreCatalog::DELIVERY),'production'=>self::choice($in,'production',StoreCatalog::PRODUCTION),'pricing'=>self::choice($in,'pricing',StoreCatalog::PRICING),'featured'=>!empty($in['featured'])?1:0,'sort_order'=>StoreCatalog::integer($in['sort_order']??0),'archived'=>!empty($in['archived'])?1:0,'revision'=>($before['revision']??0)+1,'payload'=>Protocol::encode($meta),'updated_at'=>date(DATE_ATOM)];
 if(Db::query($this->db,'SELECT product_id FROM store_product_details WHERE product_id=?',[$id])->fetchColumn())Db::query($this->db,'UPDATE store_product_details SET '.implode(',',array_map(fn($k)=>$k.'=?',array_keys($detail))).' WHERE product_id=?',[...array_values($detail),$id]);else Db::insert($this->db,'store_product_details',['product_id'=>$id]+$detail+['created_at'=>date(DATE_ATOM)]);
 if(array_key_exists('categories_present',$in)){
 $cats=$in['categories']??[];if(!is_array($cats)||count($cats)>100)throw new HttpError(422,'دسته‌ها معتبر نیستند.');$cats=array_unique(array_map(fn($v)=>StoreCatalog::integer($v,1),$cats));
 foreach($cats as $c)if(!Db::query($this->db,'SELECT id FROM store_categories WHERE id=?',[$c])->fetchColumn())throw new HttpError(422,'دسته پیدا نشد.');
 Db::query($this->db,'DELETE FROM store_category_products WHERE product_id=?',[$id]);foreach($cats as $c)Db::insert($this->db,'store_category_products',['product_id'=>$id,'category_id'=>$c]);}
 $this->audit('product.save','product',$id,$before,$data+$detail);return $id;
 });
 }
 public function variant(int $product,array $in,int $id=0):int {
 return Db::transaction($this->db,function()use($product,$in,$id){
 if(!Db::query($this->db,'SELECT id FROM products WHERE id=?',[$product])->fetchColumn())throw new HttpError(404,'محصول پیدا نشد.');
 $before=$id?Db::query($this->db,'SELECT * FROM variants WHERE id=? AND product_id=?'.($this->db->getAttribute(PDO::ATTR_DRIVER_NAME)==='mysql'?' FOR UPDATE':''),[$id,$product])->fetch():[];if($id&&!$before)throw new HttpError(404,'گونه متعلق به این محصول نیست.');
 $sku=Security::text($in,'sku',100);if(Db::query($this->db,'SELECT id FROM variants WHERE sku=? AND id<>?',[$sku,$id])->fetchColumn())throw new HttpError(422,'کد SKU تکراری است.');
 $price=StoreCatalog::integer($in['price']??null,0,1000000000);$sale=($in['sale_price']??'')===''?null:StoreCatalog::integer($in['sale_price'],0,$price);$stock=StoreCatalog::integer($in['stock']??0,0,1000000);$reason=Security::text($in,'reason',1000,false);
 if($before&&$stock!==(int)$before['stock']){if(StoreCatalog::integer($in['expected_stock']??-1)!==(int)$before['stock'])throw new HttpError(409,'موجودی تغییر کرده؛ صفحه را دوباره باز کنید.');if($reason==='')throw new HttpError(422,'علت اصلاح موجودی لازم است.');}
 $data=['sku'=>$sku,'attributes'=>Security::text($in,'attributes',255),'price'=>$price,'sale_price'=>$sale,'stock'=>$stock];
 if($id)Db::query($this->db,'UPDATE variants SET sku=?,attributes=?,price=?,sale_price=?,stock=? WHERE id=?',[...array_values($data),$id]);else $id=Db::insert($this->db,'variants',['product_id'=>$product]+$data);
 $details=['active'=>!empty($in['active'])?1:0,'unlimited'=>!empty($in['unlimited'])?1:0,'reorder_point'=>StoreCatalog::integer($in['reorder_point']??0,0,1000000)];
 if(Db::query($this->db,'SELECT variant_id FROM store_variant_details WHERE variant_id=?',[$id])->fetchColumn())Db::query($this->db,'UPDATE store_variant_details SET active=?,unlimited=?,reorder_point=? WHERE variant_id=?',[...array_values($details),$id]);else Db::insert($this->db,'store_variant_details',['variant_id'=>$id]+$details);
 if(array_key_exists('values_present',$in)){$values=$in['values']??[];if(!is_array($values)||count($values)>100)throw new HttpError(422,'ویژگی‌ها معتبر نیستند.');$axes=[];$ids=[];foreach($values as $v){$v=StoreCatalog::integer($v,1);$axis=Db::query($this->db,'SELECT attribute_id FROM store_attribute_values WHERE id=?',[$v])->fetchColumn();if(!$axis||isset($axes[$axis]))throw new HttpError(422,'از هر ویژگی برای یک گونه فقط یک مقدار انتخاب کنید.');$axes[$axis]=true;$ids[]=$v;}Db::query($this->db,'DELETE FROM store_variant_values WHERE variant_id=?',[$id]);foreach($ids as $v)Db::insert($this->db,'store_variant_values',['variant_id'=>$id,'value_id'=>$v]);}
 if(!$before||$stock!==(int)$before['stock'])Db::insert($this->db,'store_inventory_movements',['variant_id'=>$id,'delta'=>$stock-(int)($before['stock']??0),'before_stock'=>(int)($before['stock']??0),'after_stock'=>$stock,'reason'=>$reason?:'موجودی اولیه','user_id'=>$this->actor['id'],'created_at'=>date(DATE_ATOM)]);
 $this->audit('variant.save','variant',$id,$before?:[],$data+$details,$reason);return $id;
 });
 }
 public function category(array $in,int $id=0):int {
 return Db::transaction($this->db,function()use($in,$id){
 $all=Db::query($this->db,'SELECT * FROM store_categories'.($this->db->getAttribute(PDO::ATTR_DRIVER_NAME)==='mysql'?' FOR UPDATE':''))->fetchAll();$map=array_column($all,null,'id');if($id&&!isset($map[$id]))throw new HttpError(404,'دسته پیدا نشد.');
 $parent=($in['parent_id']??'')===''?null:StoreCatalog::integer($in['parent_id'],1);$p=$parent;$seen=[];while($p){if($p===$id||isset($seen[$p])||!isset($map[$p]))throw new HttpError(422,'رابطه والد دسته معتبر نیست.');$seen[$p]=true;$p=(int)$map[$p]['parent_id'];}
 $slug=self::slug($in);if(Db::query($this->db,'SELECT id FROM store_categories WHERE slug=? AND id<>?',[$slug,$id])->fetchColumn())throw new HttpError(422,'نامک دسته تکراری است.');
 $d=['parent_id'=>$parent,'title'=>Security::text($in,'title',150),'slug'=>$slug,'description'=>Security::text($in,'description',5000,false),'active'=>!empty($in['active'])?1:0,'sort_order'=>StoreCatalog::integer($in['sort_order']??0)];if($id)Db::query($this->db,'UPDATE store_categories SET '.implode(',',array_map(fn($k)=>$k.'=?',array_keys($d))).' WHERE id=?',[...array_values($d),$id]);else $id=Db::insert($this->db,'store_categories',$d);$this->audit('category.save','category',$id,$map[$id]??[],$d);return $id;
 });
 }
 public function attribute(array $in,int $id=0):int {
 return Db::transaction($this->db,function()use($in,$id){$before=$id?Db::query($this->db,'SELECT * FROM store_attributes WHERE id=?',[$id])->fetch():[];if($id&&!$before)throw new HttpError(404,'ویژگی پیدا نشد.');$key=self::slug($in,'attribute_key');if(Db::query($this->db,'SELECT id FROM store_attributes WHERE attribute_key=? AND id<>?',[$key,$id])->fetchColumn())throw new HttpError(422,'کلید ویژگی تکراری است.');
 $d=['attribute_key'=>$key,'title'=>Security::text($in,'title',150),'filterable'=>!empty($in['filterable'])?1:0,'active'=>!empty($in['active'])?1:0,'sort_order'=>StoreCatalog::integer($in['sort_order']??0)];if($id)Db::query($this->db,'UPDATE store_attributes SET attribute_key=?,title=?,filterable=?,active=?,sort_order=? WHERE id=?',[...array_values($d),$id]);else $id=Db::insert($this->db,'store_attributes',$d);$this->audit('attribute.save','attribute',$id,$before?:[],$d);return $id;});
 }
 public function value(int $attribute,array $in,int $id=0):int {
 return Db::transaction($this->db,function()use($attribute,$in,$id){if(!Db::query($this->db,'SELECT id FROM store_attributes WHERE id=?',[$attribute])->fetchColumn())throw new HttpError(404,'ویژگی پیدا نشد.');$before=$id?Db::query($this->db,'SELECT * FROM store_attribute_values WHERE id=? AND attribute_id=?',[$id,$attribute])->fetch():[];if($id&&!$before)throw new HttpError(404,'مقدار پیدا نشد.');$key=self::slug($in,'value_key');if(Db::query($this->db,'SELECT id FROM store_attribute_values WHERE attribute_id=? AND value_key=? AND id<>?',[$attribute,$key,$id])->fetchColumn())throw new HttpError(422,'کلید مقدار تکراری است.');$d=['value_key'=>$key,'title'=>Security::text($in,'title',150),'active'=>!empty($in['active'])?1:0,'sort_order'=>StoreCatalog::integer($in['sort_order']??0)];if($id)Db::query($this->db,'UPDATE store_attribute_values SET value_key=?,title=?,active=?,sort_order=? WHERE id=?',[...array_values($d),$id]);else $id=Db::insert($this->db,'store_attribute_values',['attribute_id'=>$attribute]+$d);$this->audit('value.save','value',$id,$before?:[],$d);return $id;});
 }

 public function media(int $product,int $id,array $in):void {
 Db::transaction($this->db,function()use($product,$id,$in){$before=Db::query($this->db,'SELECT * FROM store_media WHERE id=? AND product_id=?',[$id,$product])->fetch();if(!$before)throw new HttpError(404,'تصویر متعلق به این محصول نیست.');$after=['alt'=>Security::text($in,'alt',255,false),'sort_order'=>StoreCatalog::integer($in['sort_order']??0)];Db::query($this->db,'UPDATE store_media SET alt=?,sort_order=? WHERE id=?',[...array_values($after),$id]);$this->audit('media.update','media',$id,['alt'=>$before['alt'],'sort_order'=>$before['sort_order']],$after);});
 }
 public function copy(int $id):int {
 return Db::transaction($this->db,function()use($id){$p=(new StoreCatalog($this->db))->get($id,true);$in=['title'=>$p['title'].' (رونوشت)','description'=>$p['description'],'legacy_category'=>$p['category'],'slug'=>($p['slug']?:'product-'.$id).'-'.bin2hex(random_bytes(4)),'delivery'=>$p['delivery'],'production'=>$p['production'],'pricing'=>$p['pricing'],'categories_present'=>'1','categories'=>array_column($p['categories'],'id')]+$p['meta'];$new=$this->product($in);foreach($p['variants'] as $v){$v['sku'].='-'.bin2hex(random_bytes(4));$v['stock']=0;$v['values_present']='1';$v['values']=array_column(array_filter($p['values'],fn($x)=>(int)$x['variant_id']===(int)$v['id']),'id');$this->variant($new,$v);}foreach(Db::query($this->db,'SELECT * FROM store_media WHERE product_id=?',[$id])->fetchAll() as $media){unset($media['id']);$media['product_id']=$new;Db::insert($this->db,'store_media',$media);}return $new;});
 }
 }
